mapper.select:
SELECT COUNT(*)
FROM user_logs ul
LEFT JOIN users u ON ul.user_id = u.id


        AND (
            u.name LIKE CONCAT('%', #{search}, '%') OR
            ul.ip_address LIKE CONCAT('%', #{search}, '%') OR
            ul.failure_reason LIKE CONCAT('%', #{search}, '%')
        )


        AND ul.login_type = #{loginType}


        AND u.role = #{userRole}


        AND ul.success = #{success}


        AND DATE(ul.created_at) >= #{dateFrom}


        AND DATE(ul.created_at) <= #{dateTo}

SELECT 
    ul.id, ul.user_id, u.name as user_name, u.role as user_role, 
    ul.login_type, ul.login_method, ul.session_id, ul.ip_address, 
    ul.location, ul.user_agent, ul.success, ul.failure_reason, ul.created_at
FROM user_logs ul
LEFT JOIN users u ON ul.user_id = u.id


        AND (
            u.name LIKE CONCAT('%', #{search}, '%') OR
            ul.ip_address LIKE CONCAT('%', #{search}, '%') OR
            ul.failure_reason LIKE CONCAT('%', #{search}, '%')
        )


        AND ul.login_type = #{loginType}


        AND u.role = #{userRole}


        AND ul.success = #{success}


        AND DATE(ul.created_at) >= #{dateFrom}


        AND DATE(ul.created_at) <= #{dateTo}




        ORDER BY ul.created_at ASC


        ORDER BY ul.login_type ASC, ul.created_at DESC


        ORDER BY u.name ASC, ul.created_at DESC


        ORDER BY ul.ip_address ASC, ul.created_at DESC


        ORDER BY ul.created_at DESC


LIMIT #{offset}, #{limit}

SELECT login_type as loginType, COUNT(*) as count, SUM(CASE WHEN success = true THEN 1 ELSE 0 END) as successCount, SUM(CASE WHEN success = false THEN 1 ELSE 0 END) as failureCount FROM user_logs
AND DATE(created_at) >= #{dateFrom}
AND DATE(created_at) <= #{dateTo}
GROUP BY login_type ORDER BY count DESC

SELECT u.role as userRole, COUNT(*) as totalCount, SUM(CASE WHEN ul.success = true THEN 1 ELSE 0 END) as successCount, SUM(CASE WHEN ul.success = false THEN 1 ELSE 0 END) as failureCount, COUNT(DISTINCT ul.user_id) as uniqueUserCount FROM user_logs ul LEFT JOIN users u ON ul.user_id = u.id
u.role IS NOT NULL
AND DATE(ul.created_at) >= #{dateFrom}
AND DATE(ul.created_at) <= #{dateTo}
GROUP BY u.role ORDER BY totalCount DESC

SELECT DATE(created_at) as accessDate, COUNT(*) as totalCount, SUM(CASE WHEN success = true THEN 1 ELSE 0 END) as successCount, SUM(CASE WHEN success = false THEN 1 ELSE 0 END) as failureCount, COUNT(DISTINCT user_id) as uniqueUserCount, COUNT(DISTINCT CASE WHEN login_type = 'LOGIN' THEN user_id END) as loginUserCount FROM user_logs
AND DATE(created_at) >= #{dateFrom}
AND DATE(created_at) <= #{dateTo}
GROUP BY DATE(created_at) ORDER BY accessDate DESC

SELECT HOUR(created_at) as accessHour, COUNT(*) as totalCount, SUM(CASE WHEN success = true THEN 1 ELSE 0 END) as successCount, COUNT(DISTINCT user_id) as uniqueUserCount FROM user_logs
AND DATE(created_at) >= #{dateFrom}
AND DATE(created_at) <= #{dateTo}
GROUP BY HOUR(created_at) ORDER BY accessHour

SELECT CASE WHEN user_agent LIKE '%Chrome%' THEN 'Chrome' WHEN user_agent LIKE '%Firefox%' THEN 'Firefox' WHEN user_agent LIKE '%Safari%' THEN 'Safari' WHEN user_agent LIKE '%Edge%' THEN 'Edge' WHEN user_agent LIKE '%Opera%' THEN 'Opera' ELSE '기타' END as browser, COUNT(*) as count, COUNT(DISTINCT user_id) as uniqueUserCount FROM user_logs
user_agent IS NOT NULL
AND DATE(created_at) >= #{dateFrom}
AND DATE(created_at) <= #{dateTo}
GROUP BY CASE WHEN user_agent LIKE '%Chrome%' THEN 'Chrome' WHEN user_agent LIKE '%Firefox%' THEN 'Firefox' WHEN user_agent LIKE '%Safari%' THEN 'Safari' WHEN user_agent LIKE '%Edge%' THEN 'Edge' WHEN user_agent LIKE '%Opera%' THEN 'Opera' ELSE '기타' END ORDER BY count DESC

SELECT ip_address as ipAddress, COUNT(*) as accessCount, COUNT(DISTINCT user_id) as uniqueUserCount, SUM(CASE WHEN success = false THEN 1 ELSE 0 END) as failureCount, MIN(created_at) as firstAccess, MAX(created_at) as lastAccess FROM user_logs
ip_address IS NOT NULL
AND DATE(created_at) >= #{dateFrom}
AND DATE(created_at) <= #{dateTo}
GROUP BY ip_address ORDER BY accessCount DESC LIMIT #{limit}

SELECT ul.id, ul.user_id, u.name as user_name, u.role as user_role, ul.login_type, ul.login_method, ul.session_id, ul.ip_address, ul.location, ul.user_agent, ul.success, ul.failure_reason, ul.created_at FROM user_logs ul LEFT JOIN users u ON ul.user_id = u.id WHERE ul.success = false
AND DATE(ul.created_at) >= #{dateFrom}
AND DATE(ul.created_at) <= #{dateTo}
ORDER BY ul.created_at DESC LIMIT #{offset}, #{limit}

SELECT ip_address as ipAddress, COUNT(DISTINCT user_id) as userCount, COUNT(*) as accessCount, GROUP_CONCAT(DISTINCT u.name) as userNames FROM user_logs ul LEFT JOIN users u ON ul.user_id = u.id
ul.ip_address IS NOT NULL
AND DATE(ul.created_at) >= #{dateFrom}
AND DATE(ul.created_at) <= #{dateTo}
GROUP BY ip_address HAVING COUNT(DISTINCT user_id) >= #{minCount} ORDER BY userCount DESC, accessCount DESC

SELECT ul.user_id as userId, u.name as userName, u.role as userRole, DATE(ul.created_at) as accessDate, COUNT(*) as accessCount, SUM(CASE WHEN ul.success = true THEN 1 ELSE 0 END) as successCount, SUM(CASE WHEN ul.success = false THEN 1 ELSE 0 END) as failureCount FROM user_logs ul LEFT JOIN users u ON ul.user_id = u.id
ul.user_id IS NOT NULL
AND DATE(ul.created_at) >= #{dateFrom}
AND DATE(ul.created_at) <= #{dateTo}
GROUP BY ul.user_id, u.name, u.role, DATE(ul.created_at) ORDER BY accessDate DESC, accessCount DESC
